{
  "patches": [
    {
      "path": "styles.css",
      "oldString": "@media (max-width: 390px) {
  .app-header {
    flex-direction: column;
    align-items: stretch;
    padding: var(--space-md);
    gap: var(--space-sm);
  }

  #search-form {
    width: 100%;
  }

  #search {
    width: 100%;
  }

  .app-layout {
    grid-template-columns: 1fr;
    padding: var(--space-md);
    gap: var(--space-lg);
  }

  #course-nav {
    flex-direction: row;
    overflow-x: auto;
    padding-bottom: var(--space-sm);
    -webkit-overflow-scrolling: touch;
  }

  .nav-weeks {
    display: flex;
    gap: var(--space-md);
    min-width: max-content;
  }

  .nav-week {
    display: inline-flex;
    flex-direction: column;
    gap: var(--space-xs);
    min-width: 120px;
  }",
