  .app-header {
    flex-direction: column;
    align-items: stretch;
    padding: var(--space-md);
    gap: var(--space-sm);
  }

  #search-form {
    width: 100%;
  }

  #search {
    width: 100%;
  }

  .app-layout {
    grid-template-columns: 1fr;
    padding: var(--space-md);
    gap: var(--space-lg);
  }

  #course-nav {
    flex-direction: column;
    overflow-x: visible;
    padding-bottom: var(--space-sm);
    -webkit-overflow-scrolling: auto;
  }

  .nav-weeks {
    display: flex;
    flex-wrap: wrap;
    gap: var(--space-md);
    min-width: 0;
  }

  .nav-week {
    display: inline-flex;
    flex-direction: column;
    gap: var(--space-xs);
    min-width: 0;
    width: 100%;
